1	"use client";
2	
3	import { useState, useEffect, useCallback, useRef } from "react";
4	import { useTranslations } from "next-intl";
5	import useCheckMobileScreen from "@components/hooks/useCheckMobileScreen";
6	import { usePushNotifications } from "@components/hooks/usePushNotifications";
7	import { usePwaInstall } from "@components/hooks/usePwaInstall";
8	import { sendGoogleEvent } from "@utils/analytics";
9	import type { SocialPopupState } from "types/props";
10	import CloseIcon from "./CloseIcon";
11	import InstallSection from "./InstallSection";
12	import PushSection from "./PushSection";
13	import SocialLinksSection from "./SocialLinksSection";
14	
15	export const STORAGE_KEY = "social-follow-popup";
16	export const PAGE_VIEW_KEY = "social-popup-views";
17	export const SCROLL_PERCENT = 0.35;
18	export const DELAY_MS = 10_000;
19	export const COOLDOWN_DAYS = 30;
20	export const MAX_DISMISSALS = 3;
21	export const MIN_PAGE_VIEWS = 2;
22	/** How long the push success state stays visible before auto-closing. */
23	export const SUCCESS_AUTO_CLOSE_MS = 2_500;
24	
25	function getPopupState(): SocialPopupState | null {
26	  try {
27	    const raw = localStorage.getItem(STORAGE_KEY);
28	    if (!raw) return null;
29	    return JSON.parse(raw) as SocialPopupState;
30	  } catch {
31	    return null;
32	  }
33	}
34	
35	function savePopupState(state: SocialPopupState): void {
36	  try {
37	    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
38	  } catch {
39	    // localStorage unavailable
40	  }
41	}
42	
43	/** Increment and return the session page-view count.
44	 *  Deduplicates by pathname so Strict-Mode double-invocations
45	 *  and staying on the same page don't inflate the counter. */
46	function trackPageView(pathname: string): number {
47	  try {
48	    const lastPath = sessionStorage.getItem(PAGE_VIEW_KEY + "-path");
49	    if (lastPath === pathname) {
50	      return Number(sessionStorage.getItem(PAGE_VIEW_KEY) ?? "1");
51	    }
52	    const count = Number(sessionStorage.getItem(PAGE_VIEW_KEY) ?? "0") + 1;
53	    sessionStorage.setItem(PAGE_VIEW_KEY, String(count));
54	    sessionStorage.setItem(PAGE_VIEW_KEY + "-path", pathname);
55	    return count;
56	  } catch {
57	    return 1;
58	  }
59	}
60	
61	function shouldShow(): boolean {
62	  const state = getPopupState();
63	  if (!state) return true;
64	  if (state.dismissCount >= MAX_DISMISSALS) return false;
65	
66	  const elapsed = Date.now() - state.lastDismissedAt;
67	  const cooldownMs = COOLDOWN_DAYS * 24 * 60 * 60 * 1000;
68	  return elapsed >= cooldownMs;
69	}
70	
71	/** Document scroll height that must be reached (35 % of scrollable area). */
72	function getScrollThreshold(): number {
73	  const docHeight = Math.max(
74	    document.body.scrollHeight,
75	    document.documentElement.scrollHeight,
76	  );
77	  const viewportHeight = window.innerHeight;
78	  return (docHeight - viewportHeight) * SCROLL_PERCENT;
79	}
80	
81	export default function SocialFollowPopup({ pathname }: { pathname: string }) {
82	  const t = useTranslations("Components.SocialFollowPopup");
83	  const [isVisible, setIsVisible] = useState(false);
84	  const [isClosing, setIsClosing] = useState(false);
85	  const [isSubscribingPush, setIsSubscribingPush] = useState(false);
86	  const [isInstalling, setIsInstalling] = useState(false);
87	  const hasTriggeredRef = useRef(false);
88	  const hasTrackedOfferRef = useRef(false);
89	  const dialogRef = useRef<HTMLDivElement>(null);
90	  const previousFocusRef = useRef<HTMLElement | null>(null);
91	  const autoCloseTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
92	  const isMobile = useCheckMobileScreen();
93	  const { state: pushState, subscribe: subscribeToPush } =
94	    usePushNotifications();
95	  const {
96	    installState,
97	    isInstalled,
98	    canPromptInstall,
99	    showIosInstructions,
100	    showOpenInSafariHint,
101	    isIpad,
102	    iosShareLocation,
103	    promptInstall,
104	  } = usePwaInstall();
105	
106	  // Mirror latest values into refs so `dismiss` can stay referentially stable.
107	  // Its identity feeds the focus-trap/scroll-lock effect; if it changed when
108	  // installState resolves, that effect would tear down and re-run mid-popup
109	  // (stealing focus / toggling the scroll lock).
110	  const isMobileRef = useRef(isMobile);
111	  isMobileRef.current = isMobile;
112	  const installStateRef = useRef(installState);
113	  installStateRef.current = installState;
114	
115	  // Show the push CTA once there's no pending install path: app installed,
116	  // or no install prompt available (incl. after the user dismissed the
117	  // native prompt — push still works in-browser on desktop/Android).
118	  const shouldShowPushCta =
119	    (isInstalled || installState === "not-available") &&
120	    pushState !== "unsupported";
121	
122	  // Lead with install copy only when there's an actionable path (one-click
123	  // prompt, iOS steps, or the open-in-Safari hint). Without one — no-path
124	  // browsers, or already installed — fall back to the social headline so we
125	  // never promise an app the user can't get from here.
126	  const canInstall =
127	    canPromptInstall || showIosInstructions || showOpenInSafariHint;
128	  const headlineText = canInstall ? t("installHeadline") : t("headline");
129	  const subtextText = canInstall ? t("installSubtext") : t("subtext");
130	
131	  /**
132	   * Close the popup.
133	   * @param countAsDismissal When false (post-success auto-close), the
134	   *   30-day cooldown still starts but the dismissal budget isn't burned.
135	   */
136	  const dismiss = useCallback(
137	    (countAsDismissal: boolean = true) => {
138	      // `counted: false` is a post-success auto-close, not a real decline —
139	      // keep both so decline rate = dismisses where counted is true.
140	      sendGoogleEvent("push_optin_dismiss", {
141	        source: "social_follow_popup",
142	        device: isMobileRef.current ? "mobile" : "desktop",
143	        install_state: installStateRef.current,
144	        counted: countAsDismissal,
145	      });
146	      // Cancel a pending post-success auto-close so a manual dismissal
147	      // doesn't trigger a second close cycle after the timer fires.
148	      if (autoCloseTimerRef.current) {
149	        clearTimeout(autoCloseTimerRef.current);
150	        autoCloseTimerRef.current = null;
151	      }
152	    setIsClosing(true);
153	    setTimeout(() => {
154	      setIsVisible(false);
155	      setIsClosing(false);
156	
157	      const current = getPopupState();
158	      savePopupState({
159	        dismissCount: (current?.dismissCount ?? 0) + (countAsDismissal ? 1 : 0),
160	        lastDismissedAt: Date.now(),
161	      });
162	    }, 300);
163	  }, []);
164	
165	  const handleSubscribePush = useCallback(async () => {
166	    sendGoogleEvent("push_optin_click", {
167	      source: "social_follow_popup",
168	      device: isMobile ? "mobile" : "desktop",
169	    });
170	    setIsSubscribingPush(true);
171	    try {
172	      const ok = await subscribeToPush();
173	      if (ok) {
174	        sendGoogleEvent("push_optin_success", {
175	          source: "social_follow_popup",
176	          device: isMobile ? "mobile" : "desktop",
177	        });
178	        // Goal reached: show the success state briefly, then close without
179	        // burning a dismissal (closing after success isn't a rejection).
180	        autoCloseTimerRef.current = setTimeout(
181	          () => dismiss(false),
182	          SUCCESS_AUTO_CLOSE_MS,
183	        );
184	      } else {
185	        sendGoogleEvent("push_optin_failed", {
186	          source: "social_follow_popup",
187	          device: isMobile ? "mobile" : "desktop",
188	          permission:
189	            typeof Notification !== "undefined"
190	              ? Notification.permission
191	              : "unsupported",
192	        });
193	      }
194	    } finally {
195	      setIsSubscribingPush(false);
196	    }
197	  }, [subscribeToPush, isMobile, dismiss]);
198	
199	  const handleInstall = useCallback(async () => {
200	    if (!canPromptInstall) return;
201	    sendGoogleEvent("pwa_install_click", {
202	      source: "social_follow_popup",
203	      device: isMobile ? "mobile" : "desktop",
204	    });
205	
206	    setIsInstalling(true);
207	    try {
208	      const outcome = await promptInstall();
209	      sendGoogleEvent("pwa_install_result", {
210	        source: "social_follow_popup",
211	        device: isMobile ? "mobile" : "desktop",
212	        outcome,
213	      });
214	      // Stay open on "accepted": the install section disappears and the
215	      // push CTA takes its place — the second step of the funnel.
216	    } finally {
217	      setIsInstalling(false);
218	    }
219	  }, [canPromptInstall, isMobile, promptInstall]);
220	
221	  // Clear any pending auto-close timer on unmount
222	  useEffect(() => {
223	    return () => {
224	      if (autoCloseTimerRef.current) clearTimeout(autoCloseTimerRef.current);
225	    };
226	  }, []);
227	
228	  // Escape key + focus trap for desktop modal (WAI-ARIA dialog pattern),
229	  // plus body scroll lock and focus restore.
230	  useEffect(() => {
231	    if (!isVisible) return;
232	
233	    const handleKeyDown = (e: KeyboardEvent) => {
234	      if (e.key === "Escape") {
235	        dismiss();
236	        return;
237	      }
238	
239	      // Focus trap only applies to desktop modal
240	      if (e.key !== "Tab" || isMobile) return;
241	      const dialog = dialogRef.current;
242	      if (!dialog) return;
243	
244	      const focusable = dialog.querySelectorAll<HTMLElement>(
245	        'a[href], button:not([disabled]), [tabindex]:not([tabindex="-1"])',
246	      );
247	      if (focusable.length === 0) return;
248	
249	      const first = focusable[0];
250	      const last = focusable[focusable.length - 1];
251	
252	      if (e.shiftKey && document.activeElement === first) {
253	        e.preventDefault();
254	        last.focus();
255	      } else if (!e.shiftKey && document.activeElement === last) {
256	        e.preventDefault();
257	        first.focus();
258	      }
259	    };
260	
261	    let didLock = false;
262	    let previousBodyOverflow: string | null = null;
263	    if (!isMobile) {
264	      // Remember the focused element, move focus into the dialog, and lock
265	      // background scroll while the modal is open (desktop only — the
266	      // mobile toast is intentionally nonmodal).
267	      previousFocusRef.current =
268	        document.activeElement instanceof HTMLElement
269	          ? document.activeElement
270	          : null;
271	      const firstFocusable = dialogRef.current?.querySelector<HTMLElement>(
272	        'a[href], button:not([disabled])',
273	      );
274	      firstFocusable?.focus();
275	
276	      previousBodyOverflow = document.body.style.overflow;
277	      document.body.style.overflow = "hidden";
278	      didLock = true;
279	    }
280	
281	    document.addEventListener("keydown", handleKeyDown);
282	    return () => {
283	      document.removeEventListener("keydown", handleKeyDown);
284	      // Restore based on whether this effect run actually locked, not on
285	      // the (correct but indirect) isMobile closure value.
286	      if (didLock) {
287	        document.body.style.overflow = previousBodyOverflow ?? "";
288	        previousFocusRef.current?.focus?.();
289	        previousFocusRef.current = null;
290	      }
291	    };
292	  }, [isVisible, isMobile, dismiss]);
293	
294	  useEffect(() => {
295	    if (typeof window === "undefined") return;
296	
297	    // Always count page views so the counter increments on every
298	    // route change, even when other guards prevent the popup.
299	    const views = trackPageView(pathname);
300	
301	    if (hasTriggeredRef.current) return;
302	    if (!shouldShow()) return;
303	    if (views < MIN_PAGE_VIEWS) return;
304	
305	    const getScrollY = () =>
306	      window.scrollY ||
307	      document.documentElement.scrollTop ||
308	      document.body.scrollTop ||
309	      0;
310	
311	    let scrolled = false;
312	    let timerFired = false;
313	
314	    const tryShow = () => {
315	      if (hasTriggeredRef.current) return;
316	      // OR logic: either signal alone proves engagement
317	      if (scrolled || timerFired) {
318	        hasTriggeredRef.current = true;
319	        setIsVisible(true);
320	      }
321	    };
322	
323	    const handleScroll = () => {
324	      if (getScrollY() >= getScrollThreshold()) {
325	        scrolled = true;
326	        tryShow();
327	      }
328	    };
329	
330	    const timerId = setTimeout(() => {
331	      timerFired = true;
332	      tryShow();
333	    }, DELAY_MS);
334	
335	    document.addEventListener("scroll", handleScroll, { passive: true });
336	
337	    return () => {
338	      document.removeEventListener("scroll", handleScroll);
339	      clearTimeout(timerId);
340	    };
341	    // Re-evaluate on route change so page-view count can reach MIN_PAGE_VIEWS
342	  }, [pathname]);
343	
344	  useEffect(() => {
345	    if (!isVisible || hasTrackedOfferRef.current) return;
346	    hasTrackedOfferRef.current = true;
347	    sendGoogleEvent("push_optin_offer_view", {
348	      source: "social_follow_popup",
349	      device: isMobile ? "mobile" : "desktop",
350	      state: pushState,
351	      install_state: installState,
352	    });
353	  }, [isVisible, isMobile, pushState, installState]);
354	
355	  if (!isVisible) return null;
356	
357	  /* ------------------------------------------------------------------ */
358	  /*  Mobile: nonmodal bottom toast (less intrusive, avoids Google      */
359	  /*  mobile interstitial penalty).                                     */
360	  /* ------------------------------------------------------------------ */
361	  if (isMobile) {
362	    return (
363	      <div
364	        className={`fixed bottom-16 inset-x-0 z-modal p-4 ${
365	          isClosing ? "animate-slide-down" : "animate-slide-up"
366	        }`}
367	        role="complementary"
368	        aria-label={canInstall ? t("ariaInstall") : t("aria")}
369	      >
370	        <div className="relative w-full max-h-[80vh] overflow-hidden flex flex-col bg-background rounded-card border border-border shadow-lg">
371	          {/* Gradient accent bar */}
372	          <div className="h-1 bg-gradient-to-r from-primary via-primary to-primary/70" />
373	
374	          <div className="p-card-padding flex flex-col gap-element-gap-sm overflow-y-auto overscroll-contain min-h-0">
375	            {/* Close button */}
376	            <button
377	              onClick={() => dismiss()}
378	              className="absolute top-4 right-4 p-1 rounded-full text-foreground/60 hover:text-foreground hover:bg-muted transition-[color,background-color] duration-fast focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2"
379	              aria-label={t("close")}
380	            >
381	              <CloseIcon />
382	            </button>
383	
384	            {/* Header */}
385	            <div className="text-center">
386	              <h2 className="heading-3 text-foreground-strong mb-2 text-balance">
387	                {headlineText}
388	              </h2>
389	              <p className="body-small text-foreground/75 text-pretty">{subtextText}</p>
390	            </div>
391	
392	            <InstallSection
393	              canPromptInstall={canPromptInstall}
394	              showIosInstructions={showIosInstructions}
395	              showOpenInSafariHint={showOpenInSafariHint}
396	              isIpad={isIpad}
397	              iosShareLocation={iosShareLocation}
398	              isInstalling={isInstalling}
399	              onInstall={handleInstall}
400	            />
401	
402	            {shouldShowPushCta ? (
403	              <PushSection
404	                pushState={pushState}
405	                isSubscribing={isSubscribingPush}
406	                onSubscribe={handleSubscribePush}
407	              />
408	            ) : null}
409	
410	            <SocialLinksSection variant="mobile" />
411	
412	            {/* Dismiss */}
413	            <button
414	              onClick={() => dismiss()}
415	              className="body-small text-foreground/50 hover:text-foreground/70 transition-colors duration-fast py-1.5 rounded-button focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2"
416	            >
417	              {t("close")}
418	            </button>
419	          </div>
420	        </div>
421	      </div>
422	    );
423	  }
424	
425	  /* ------------------------------------------------------------------ */
426	  /*  Desktop: centered modal (higher conversion, no Google penalty).   */
427	  /* ------------------------------------------------------------------ */
428	  return (
429	    <div
430	      ref={dialogRef}
431	      className={`fixed inset-0 z-modal flex-center p-4 ${
432	        isClosing ? "animate-disappear" : "animate-appear"
433	      }`}
434	      role="dialog"
435	      aria-modal="true"
436	      aria-label={canInstall ? t("ariaInstall") : t("aria")}
437	    >
438	      {/* Backdrop */}
439	      <div
440	        className="absolute inset-0 bg-foreground/50"
441	        onClick={() => dismiss()}
442	        aria-hidden="true"
443	      />
444	
445	      {/* Panel */}
446	      <div
447	        className={`relative w-full max-w-md max-h-[90vh] overflow-hidden flex flex-col bg-background rounded-card border border-border shadow-lg transition-transform duration-slower ${
448	          isClosing ? "scale-95" : "scale-100"
449	        }`}
450	      >
451	        {/* Gradient accent bar */}
452	        <div className="h-1.5 bg-gradient-to-r from-primary via-primary to-primary/70" />
453	
454	        {/* Close button */}
455	        <button
456	          onClick={() => dismiss()}
457	          className="absolute top-4 right-4 z-10 p-1 rounded-full text-foreground/60 hover:text-foreground hover:bg-muted transition-[color,background-color] duration-fast focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2"
458	          aria-label={t("close")}
459	        >
460	          <CloseIcon />
461	        </button>
462	
463	        {/* Content (scrolls; panel stays put so the close button is pinned) */}
464	        <div className="p-6 sm:p-8 flex flex-col gap-6 overflow-y-auto overscroll-contain min-h-0">
465	          {/* Header section */}
466	          <div className="flex flex-col gap-3 text-center">
467	            {/* Icon accent */}
468	            <div className="w-12 h-12 rounded-full bg-primary/10 flex-center mx-auto">
469	              <svg
470	                xmlns="http://www.w3.org/2000/svg"
471	                viewBox="0 0 24 24"
472	                fill="none"
473	                stroke="currentColor"
474	                strokeWidth={1.5}
475	                className="w-6 h-6 text-primary"
476	                aria-hidden="true"
477	              >
478	                <path
479	                  strokeLinecap="round"
480	                  strokeLinejoin="round"
481	                  d="M21 8.25c0-2.485-2.099-4.5-4.688-4.5-1.935 0-3.597 1.126-4.312 2.733-.715-1.607-2.377-2.733-4.313-2.733C5.1 3.75 3 5.765 3 8.25c0 7.22 9 12 9 12s9-4.78 9-12Z"
482	                />
483	              </svg>
484	            </div>
485	
486	            {/* Headline */}
487	            <h2 className="heading-2 text-foreground-strong text-balance">
488	              {headlineText}
489	            </h2>
490	
491	            {/* Subtext */}
492	            <p className="body-normal text-foreground/75 leading-relaxed text-pretty">
493	              {subtextText}
494	            </p>
495	          </div>
496	
497	          <InstallSection
498	            canPromptInstall={canPromptInstall}
499	            showIosInstructions={showIosInstructions}
500	            showOpenInSafariHint={showOpenInSafariHint}
501	            isIpad={isIpad}
502	            iosShareLocation={iosShareLocation}
503	            isInstalling={isInstalling}
504	            onInstall={handleInstall}
505	          />
506	
507	          <SocialLinksSection variant="desktop" />
508	
509	          {shouldShowPushCta ? (
510	            <PushSection
511	              pushState={pushState}
512	              isSubscribing={isSubscribingPush}
513	              onSubscribe={handleSubscribePush}
514	            />
515	          ) : null}
516	
517	          {/* Dismiss button */}
518	          <button
519	            onClick={() => dismiss()}
520	            className="body-small text-foreground/50 hover:text-foreground/70 transition-colors duration-fast py-2 rounded-button focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2"
521	          >
522	            {t("close")}
523	          </button>
524	        </div>
525	      </div>
526	    </div>
527	  );
528	}
